WAITING = "Vermont"


def _sched(b, x):
    tax, lo = 0.0, 0
    for hi, rate in b:
        top = x if hi is None else min(x, hi)
        if top > lo: tax += (top - lo) * rate
        if hi is None or x <= hi: break
        lo = hi
    return tax


def _upto(steps, x):
    return next(a for lim, a in steps if lim is None or x <= lim)


def state_tax(code, salary, status="single", pretax=0, fed_tax=0):
    """{"taxable", "tax", "local", "pay": [(name, amount)], "pay_total", "total"} for a yearly salary, as T.stateTax does in assets/tools.js."""
    s, f = STATES[code], STATES[code][status]
    wages = salary if s.get("pretax_taxed") else salary - pretax
    std, ex, credit = f["d"], f["e"], f["c"]
    if s.get("ex_max") and wages > s["ex_max"][status]: ex = 0
    if s.get("ex_steps"): ex = _upto(s["ex_steps"], wages) * (2 if status == "joint" else 1)
    if s.get("ex_by"): ex = _upto(s["ex_by"][status], wages)
    if s.get("std_phase"):
        at, r = s["std_phase"][status]; std = max(0, std - r * max(0, wages - at))
    if s.get("std_steps"):
        at, step, less, floor = s["std_steps"][status]; std = max(floor, std - less * math.ceil(max(0, wages - at) / step))
    if s.get("credit_phase"):
        at, r = s["credit_phase"][status]; credit = max(0, credit - r * max(0, wages - at))
    if s.get("credit_max") and wages > s["credit_max"][status]: credit = 0
    ded = 0
    if s.get("fed_ded"):
        fd = s["fed_ded"]
        cap = _upto(fd["cap_steps"][status], wages) if fd.get("cap_steps") else (fd.get("cap") or {}).get(status)
        ded = _upto(fd["steps"], wages) * fed_tax
        if cap is not None: ded = min(cap, ded)
    taxable = max(0, salary - pretax - FED_STD[status]) if s["base"] == "fed" else max(0, wages - std - ex - ded)
    b = f["b"]
    tax = _sched(b, taxable)
    if s.get("steps_add") and taxable > 0:
        # Connecticut: amounts added by wage band (TPG-211 Tables C and D), each [from wages, band width, added per band, at most]
        tax += sum(min(most, step * math.ceil((wages - at) / width)) for at, width, step, most in s["steps_add"][status] if wages > at)
    if s.get("add_over") and taxable > s["add_over"][0]: tax += s["add_over"][1]
    if s.get("recapture") and wages > s["recapture"]["from_income"]:
        # New York: above $107,650 of income the benefit of the lower rates is taken back, one bracket at a time over $50,000 (IT-201 worksheets)
        first = s["recapture"][status]
        k = max(first, next(i for i, (hi, _) in enumerate(b) if hi is None or taxable <= hi))
        if wages > s["recapture"]["flat_over"]: tax = taxable * b[-1][1]
        else:
            low = b[k - 1][0]
            base = 0 if k == first else low * b[k - 1][1] - _sched(b, low)
            start = s["recapture"]["from_income"] if k == first else low
            tax = tax + base + (taxable * b[k][1] - tax - base) * min(1, (wages - start) / 50000)
    tax = max(0, tax - credit)
    if s.get("credit_share"): tax *= 1 - _upto(s["credit_share"][status], wages)       # Connecticut's personal tax credit: a share of the tax (Table E)
    local = taxable * s["local_rate"][0] if s.get("local_rate") else 0
    pay = []
    for name, rate, cap, most in s["pay"]:
        a = rate * (salary if cap is None else min(salary, cap))
        pay.append((name, a if most is None else min(a, most)))
    t = sum(a for _, a in pay)
    return {"taxable": taxable, "tax": tax, "local": local, "pay": pay, "pay_total": t, "total": tax + local + t}




HAND = [("NC", 75000, "single", 0, 2483.775, 0), ("GA", 75000, "single", 0, 2994, 0), ("IL", 75000, "single", 0, 3567.7125, 0), ("IL", 300000, "single", 0, 14850, 0), ("PA", 75000, "single", 5000, 2302.5, 52.5),
        ("CA", 75000, "single", 0, 2665.12, 975), ("TX", 75000, "single", 0, 0, 0), ("IA", 75000, "single", 0, 2198.2, 0), ("MT", 75000, "single", 0, 2876.6, 0), ("MS", 75000, "single", 0, 2268, 0),
        ("KY", 75000, "single", 0, 2507.4, 0), ("MA", 75000, "single", 0, 3530, 345), ("NJ", 75000, "single", 0, 2596, 505.4), ("WA", 100000, "single", 0, 0, 1387.2), ("AK", 100000, "single", 0, 0, 271), ("HI", 100000, "joint", 0, None, 390),
        ("MI", 75000, "single", 0, 2936.75, 0), ("CO", 75000, "single", 0, 2591.6, 330), ("OH", 75000, "single", 0, 1619, 0), ("WI", 75000, "single", 0, 2943.52, 0), ("SC", 75000, "single", 0, 2657.32, 0), ("UT", 75000, "single", 0, 3103.45, 0),
        ("NY", 75000, "single", 0, 3453.0, 355.2), ("NY", 150000, "single", 0, 8291.05775, 443.11)]


def check():
    for c, s in STATES.items():
        assert s["kind"] in ("none", "flat", "graduated") and s["src"], c
        for st in ("single", "joint"):
            b = s[st]["b"]; assert b[-1][0] is None and all(x[0] < y[0] for x, y in zip(b[:-2], b[1:-1])), (c, st)
            assert all(0 <= r < .14 for _, r in b), (c, st)
    for c, sal, st, pre, tax, pay in HAND:
        r = state_tax(c, sal, st, pre)
        assert tax is None or abs(r["tax"] - tax) < .01, (c, r["tax"], tax)
        assert abs(r["pay_total"] - pay) < .01, (c, r["pay_total"], pay)
    assert abs(state_tax("MO", 75000, "single", 0, 7670)["tax"] - 2533.59) < .01
    assert abs(state_tax("AL", 75000, "single", 0, 7670)["tax"] - 3126.5) < .01
    assert abs(state_tax("OR", 75000, "single", 0, 7670)["tax"] - 5058.625) < .01 and abs(state_tax("OR", 75000)["pay_total"] - 525) < .01
    r = state_tax("MD", 75000); assert abs(r["tax"] - 3198.875) < .01 and abs(r["local"] - 2190.4) < .01
    assert abs(state_tax("NY", 300000)["tax"] - 20002) < .01
    # Connecticut, worked by hand with TPG-211 (2026): $75,000 single (Code F): no exemption above $44,000, Table B $2,000 + 5.5% of
    # $25,000 = $3,375, Table C $100 (more than $71,500, up to $76,500), no recapture, no credit above $64,500: $3,475; CT PL 0.5%.
    r = state_tax("CT", 75000); assert abs(r["tax"] - 3475) < .01 and abs(r["pay_total"] - 375) < .01
    # $300,000 single: $14,000 + 6.9% of $50,000 = $17,450, Table C $250, Table D $2,050 (more than $295,000, up to $300,000): $19,750
    assert abs(state_tax("CT", 300000)["tax"] - 19750) < .01 and abs(state_tax("CT", 300000)["pay_total"] - 922.5) < .01
    # $150,000 joint (Code C): $4,000 + 5.5% of $50,000 = $6,750, Table C $500, no recapture up to $210,000: $7,250
    assert abs(state_tax("CT", 150000, "joint")["tax"] - 7250) < .01
    # IP 2026(1) Example 8: $700 a week, Code F, $17.65 a week from the wage-bracket tables; the rules give $17.79 (exemption $8,000,
    # $1,028 of tax, 10% credit): the tables work per wage band, so they agree within a band
    assert abs(state_tax("CT", 700 * 52)["tax"] / 52 - 17.65) < .25 and abs(state_tax("CT", 700 * 52)["tax"] - 925.2) < .01
    # Arkansas, DFA Withholding Tax Formula for 2026 (3.7%). Its Example: $2,127 a month, two exemptions: $25,524 - $2,470 = $23,054
    # ($23,050 at the $50 midrange), 3.4% less $287.97 = $495.73, rounded $496, less 2 x $29 = $438 a year ($36.50 a month)
    assert abs(state_tax("AR", 25524, "joint")["tax"] - 438) < .5
    # $75,000 single: $72,530 ($72,550 midrange) x 3.7% - $367.16 = $2,317, less $29 = $2,288 (the calculator skips the midrange: $2,287.45)
    assert abs(state_tax("AR", 75000)["tax"] - 2288) < 1
    # $150,000 single: $147,530 x 3.7% - $79.90 = $5,378.71, rounded $5,379, less $29 = $5,350
    assert abs(state_tax("AR", 150000)["tax"] - 5350) < 1
    # Maine, withholding tables revised August 2026. Example 3: married, $4,500 a week, two allowances: $234,000 - $10,600 - $22,945
    # (the phased standard deduction) = $200,455, $8,237 + 7.15% of $70,705 = $13,292 a year
    assert abs(state_tax("ME", 234000, "joint")["tax"] - 13292) < 1
    # Example 2: single, $1,000 a week, two allowances: $52,000 - $10,600 - $12,850 = $28,550, $1,589 + 6.75% of $1,150 = $1,667.
    # The calculator counts one allowance for a single filer, so the second allowance goes in as $5,300 taken off before tax.
    assert abs(state_tax("ME", 52000, "single", 5300)["tax"] - 1667) < 1
    # Example 1: $300 a week, two allowances: the income after allowances and deduction is below zero, so nothing is withheld
    assert state_tax("ME", 15600, "single", 5300)["tax"] == 0
    # Paid Family and Medical Leave: $375 on $75,000 (the state's premium chart), at most $922.50
    assert abs(state_tax("ME", 75000)["pay_total"] - 375) < .01 and abs(state_tax("ME", 250000)["pay_total"] - 922.5) < .01
    return len(STATES)


if __name__ == "__main__":
    print(check(), "states checked")
